Method.Implementation:
$$$TRACE("PutBatch")
Set tStatus = $$$OK
Try {
	If '$IsObject($get(pBatch)) Set tStatus = $$$ERROR($$$ObjectInstanceRequired) Quit
	If '$IsObject(characterStream) {

		Set characterStream = ##class(%GlobalCharacterStream).%New()

	}
	If $IsObject(pBatch.Request) {
		Set tStatus = ..Email278updatePutRecord(characterStream, pBatch.Request)
		If $$$ISERR(tStatus) Quit
	}

	Set seqKey = ""
	For {
		Set tElement = pBatch.ServiceLevel.GetNext(.seqKey)
		If (seqKey = "") Quit
		If $IsObject(tElement) {
			$$$TRACE("ServiceLevel: " _ tElement.Record)
			Set tStatus = ..Sh2782000FPutRecord(characterStream, tElement.Record)

			If $$$ISERR(tStatus) Quit
		}
		Set tStatus = pBatch.ServiceLevel.%UnSwizzleAt(seqKey)
		If $$$ISERR(tStatus) Quit
	}
	If $$$ISERR(tStatus) Quit

	If $IsObject(pBatch.Message) {
		Set tStatus = ..MessagePutObject(characterStream,pBatch.Message,0)
		If $$$ISERR(tStatus) Quit
	}

} Catch ex {
	Set tStatus = $$$SystemError
}
Quit tStatus

Try {
	$$$TRACE("MessagePutObject")
	Set tStatus = $$$OK
	If '$IsObject(pStream) {

		Set pStream = ##class(%GlobalCharacterStream).%New()

	}
	Set tHasTopFields = $parameter(pObject,"INCLUDETOPFIELDS")

	Set tStatus = ..MessagePutRecord(pStream, pObject, tHasTopFields)
	If $$$ISERR(tStatus) Quit

}
Catch ex {
	Set tStatus = ex.AsStatus()
}
Quit tStatus
